const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解一元一次方程：4x + 1 = 1x + 9' },
      { kind: 'text', payload: '移项' },
      { kind: 'text', payload: '4x − 1x = 9 − 1' },
      { kind: 'text', payload: '合并同类项' },
      { kind: 'text', payload: '3x = 8' },
      { kind: 'text', payload: '系数化为 1' },
      { kind: 'text', payload: 'x = 8/3（两边同除以 3）' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '3' }
    ];
  },
  render: function (input, metrics) {
    function rrect(x, y, w, h, r) {
      return [
        ['M', x + r, y],
        ['L', x + w - r, y],
        ['Q', x + w, y, x + w, y + r],
        ['L', x + w, y + h - r],
        ['Q', x + w, y + h, x + w - r, y + h],
        ['L', x + r, y + h],
        ['Q', x, y + h, x, y + h - r],
        ['L', x, y + r],
        ['Q', x, y, x + r, y],
        ['Z']
      ];
    }
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var cardX = w * 0.10;
    var cardW = w * 0.80;
    var cardH = h * 0.18;
    var gap = h * 0.055;
    var cardY0 = h * 0.20;
    var radius = Math.min(18, cardH * 0.20);
    var badgeR = Math.min(22, cardH * 0.22);
    var badgeCx = cardX + Math.max(34, cardW * 0.075);
    var textX = cardX + Math.max(70, cardW * 0.14);
    var paths = [];
    var children = [];
    children.push({ type: 'label', contentId: metrics[0].contentId, anchor: { x: w / 2, y: h * 0.09 }, hAlign: 'center', vAlign: 'middle', color: '#14213D' });
    var fills = ['#EEF4FF', '#EAF7F1', '#FFF4E8'];
    for (var i = 0; i < 3; i++) {
      var cardY = cardY0 + i * (cardH + gap);
      var cardId = 'card' + i;
      paths.push({ id: cardId, commands: rrect(cardX, cardY, cardW, cardH, radius) });
      children.push({ type: 'path', pathId: cardId, fill: fills[i] });
      var badgeId = 'badge' + i;
      paths.push({ id: badgeId, commands: visualSdk.circle(badgeCx, cardY + cardH / 2, badgeR) });
      children.push({ type: 'path', pathId: badgeId, fill: '#2F6FEB' });
      children.push({ type: 'label', contentId: metrics[7 + i].contentId, anchor: { x: badgeCx, y: cardY + cardH / 2 }, hAlign: 'center', vAlign: 'middle', color: '#FFFFFF' });
      children.push({ type: 'label', contentId: metrics[1 + 2 * i].contentId, anchor: { x: textX, y: cardY + cardH * 0.34 }, hAlign: 'left', vAlign: 'middle', color: '#14213D' });
      children.push({ type: 'label', contentId: metrics[2 + 2 * i].contentId, anchor: { x: textX, y: cardY + cardH * 0.72 }, hAlign: 'left', vAlign: 'middle', color: '#1F2937' });
    }
    for (var j = 0; j < 2; j++) {
      var startY = cardY0 + j * (cardH + gap) + cardH + gap * 0.20;
      var endY = cardY0 + (j + 1) * (cardH + gap) - gap * 0.15;
      var arrowId = 'arrow' + j;
      paths.push({ id: arrowId, commands: visualSdk.arrow(w / 2, startY, w / 2, endY, {}) });
      children.push({ type: 'path', pathId: arrowId, fill: '#6B7A99' });
    }
    return {
      schemaVersion: 1,
      sceneId: 'equation-flow-card',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
